using System;using System.IO;using System.Linq;using System.Threading;using System.Collections.Generic;using System.Security.Cryptography;
namespace ServiceTool{
internal static class OnlineProgressTests{
static void Validate(List<TransferProgress> events){if(!events.Any(p=>p.Bytes>0&&p.Total>0)||!events.Any(p=>p.Stage.StartsWith("Проверяем"))||!events.Any(p=>p.Stage.StartsWith("Сохраняем"))||!events.Last().Complete)throw new Exception("Missing real progress stages");if(events.Take(events.Count-1).Any(p=>p.Complete))throw new Exception("Premature completion");Console.WriteLine("Progress: "+events.Count+" events, "+events.Max(p=>p.Bytes)+" bytes, stages and completion verified");}
static int Main(){try{
string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"online-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var events=new List<TransferProgress>();
var remote=SoftwareSources.Latest("7zip");Console.WriteLine("Official software: "+remote.Version);var package=SoftwarePackageStorage.Download(remote,root,Console.WriteLine,()=>false,events.Add);Validate(events);if(!File.Exists(package.File))throw new Exception("Software publication missing");
bool softwareCancelled=false;bool stopSoftware=false;try{SoftwarePackageStorage.Download(remote,root,Console.WriteLine,()=>stopSoftware,p=>{if(p.Bytes>0)stopSoftware=true;});}catch(OperationCanceledException){softwareCancelled=true;}if(!softwareCancelled||!File.Exists(package.File))throw new Exception("Software cancellation damaged old file");
var local=LibraryCatalog.All().First(p=>p.Kind==LibraryKind.DotNet&&p.Version=="8.0.31"&&p.RuntimeFamily=="Microsoft.NETCore.App"&&p.Architecture=="x64");var update=DotNetUpdates.Check(new[]{local},CancellationToken.None).Single();string old=Path.Combine(root,local.RelativePath);Directory.CreateDirectory(Path.GetDirectoryName(old));File.WriteAllText(old,"isolated old installer fixture");using(var sha=SHA256.Create())local.Sha256=BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(old))).Replace("-","");
events.Clear();Console.WriteLine("Official runtime: "+update.Version);DotNetUpdates.Download(update,root,CancellationToken.None,null,events.Add);Validate(events);if(File.Exists(old)||!File.Exists(Path.Combine(Path.GetDirectoryName(old),update.FileName)))throw new Exception("Runtime publication incorrect");
File.WriteAllText(old,"preserve old fixture");var cancel=new CancellationTokenSource();bool stopped=false;events.Clear();try{DotNetUpdates.Download(update,root,cancel.Token,null,p=>{events.Add(p);if(p.Bytes>0)cancel.Cancel();});}catch(OperationCanceledException){stopped=true;}if(!stopped||events.Any(p=>p.Complete)||File.ReadAllText(old)!="preserve old fixture")throw new Exception("Cancellation preservation failed");
string expectedHash=update.Hash;update.Hash=new string('0',128);events.Clear();bool rejected=false;try{DotNetUpdates.Download(update,root,CancellationToken.None,null,events.Add);}catch(InvalidDataException){rejected=true;}finally{update.Hash=expectedHash;}if(!rejected||events.Any(p=>p.Complete)||File.ReadAllText(old)!="preserve old fixture")throw new Exception("Bad hash completion/preservation");
Console.WriteLine("PASS: official 7-Zip and .NET downloads, real byte totals, validation/publication stages, signature/hash/product validation, cancellation with old-file preservation. No installers executed. Files: "+root);return 0;
}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}}
